function foldName(s: string) {
  return s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

export function photoOfProduct(nome?: string | null, codigo?: string | null): string | undefined {
  if (codigo && PRODUCT_PHOTO_BY_CODIGO[codigo]) return PRODUCT_PHOTO_BY_CODIGO[codigo];
  if (!nome) return undefined;
  const key = foldName(nome);
  if (PRODUCT_PHOTO_BY_NAME[key]) return PRODUCT_PHOTO_BY_NAME[key];
  const loose = key.replace(/1\/2/g, "1-2").replace(/\s+/g, " ").trim();
  return PRODUCT_PHOTO_BY_NAME[loose];
}
